			}

			slotStats = make(map[[fieldparams.RootLength]byte][]dataColumnLogEntry)
		}
	}
}

func prettyMinMaxAverage(min, max, average time.Duration) string {
	return fmt.Sprintf("[min: %v, avg: %v, max: %v]", min, average, max)
}
"}

